/*
Theme Name: Astra Child
Template: astra
Author: Antigravity
Description: A child theme for Astra to implement the custom Trident homepage.
Version: 1.0.0
*/

/* Custom styles from trident-homepage.html */
:root {
  --ink-navy:    #0A1628;
  --brand-navy:  #0D2147;
  --signal-cyan: #0099D6;
  --frost:       #E8F6FC;
  --cloud-white: #F8FAFB;
  --gray-50:     #F2F4F6;
  --gray-100:    #E4E8EC;
  --gray-300:    #B0BAC5;
  --gray-500:    #6B7A8D;
  --gray-700:    #3A4553;
  --charcoal:    #1C2B3A;
  --pure-white:  #FFFFFF;
  --font: 'Questrial', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --max-w: 1280px;
  --nav-h: 88px;
}

*, *::before, *::after { margin:0; padding:0; box-sizing:border-box; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font);
  background: var(--pure-white);
  color: var(--charcoal);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { text-decoration: none; color: inherit; }
img { display: block; max-width: 100%; }


/* ════════════════════════════════
   NAVBAR
════════════════════════════════ */
.navbar {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 200;
  height: var(--nav-h);
  background: rgba(255,255,255,0.97);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border-bottom: 1px solid rgba(10,22,40,0.08);
  transition: background 300ms ease, height 300ms ease, box-shadow 300ms ease;
}
.navbar.scrolled {
  height: 56px;
  background: rgba(255,255,255,0.99);
  border-bottom: 1px solid rgba(10,22,40,0.10);
  box-shadow: 0 2px 16px rgba(10,22,40,0.08);
}
.nav-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  height: 100%;
  padding: 0 80px;
  display: flex;
  align-items: center;
}
.nav-logo { display:flex; align-items:center; flex-shrink:0; margin-right:48px; }
.nav-logo img { height:52px; width:auto; object-fit:contain; transition: height 300ms; }
.navbar.scrolled .nav-logo img { height:40px; }

.nav-links { display:flex; align-items:center; gap:2px; flex:1; list-style:none; }
.nav-links > li { position:relative; }
.nav-links > li > a {
  display:flex; align-items:center; gap:5px;
  padding:8px 13px;
  font-size:14px;
  color:rgba(10,22,40,0.65);
  letter-spacing:0.01em;
  transition:color 200ms ease;
  white-space:nowrap;
  position:relative;
}
.nav-links > li > a:hover,
.nav-links > li > a.active { color:var(--ink-navy); }
.nav-links > li > a.active::after {
  content:"";
  position:absolute;
  bottom:0; left:13px; right:13px;
  height:2px;
  background:var(--signal-cyan);
  border-radius:1px;
}
.nav-chevron {
  width:11px; height:11px;
  stroke:currentColor; fill:none; stroke-width:2;
  flex-shrink:0;
  transition:transform 200ms ease;
}
.nav-links > li:hover .nav-chevron { transform:rotate(180deg); }

.dropdown {
  position:absolute;
  top:calc(100% + 6px); left:0;
  min-width:310px;
  background:var(--pure-white);
  border:1px solid var(--gray-100);
  border-radius:4px;
  box-shadow:0 12px 40px rgba(10,22,40,0.14);
  opacity:0; transform:translateY(-6px);
  pointer-events:none;
  transition:opacity 200ms ease, transform 200ms ease;
  z-index:300; overflow:hidden;
}
.nav-links > li:hover .dropdown { opacity:1; transform:translateY(0); pointer-events:auto; }
.dropdown-item {
  display:block; padding:14px 20px;
  border-bottom:1px solid var(--gray-100);
  transition:background 150ms ease;
}
.dropdown-item:last-child { border-bottom:none; }
.dropdown-item:hover { background:var(--frost); }
.dropdown-item .d-title { font-size:13px; color:var(--ink-navy); display:block; margin-bottom:3px; }
.dropdown-item .d-desc { font-size:11px; color:var(--gray-500); display:block; line-height:1.5; }

.nav-cta {
  margin-left:auto;
  display:inline-flex; align-items:center;
  height:40px; padding:0 22px;
  background:var(--signal-cyan);
  color:var(--pure-white);
  font-family:var(--font);
  font-size:13px; letter-spacing:0.04em;
  border-radius:2px; border:none; cursor:pointer;
  transition:background 200ms ease; flex-shrink:0;
}
.nav-cta:hover { background:#0082b8; }


/* ════════════════════════════════
   HERO
════════════════════════════════ */
.hero {
  position:relative;
  width:100%;
  margin-top:0;
  height:90vh;
  min-height:580px;
  max-height:860px;
  overflow:hidden;
  display:flex;
  align-items:center;
}
.hero-bg {
  position:absolute; inset:0; z-index:0;
  background-image:url("data:image/jpeg;base64,");
  background-size:cover;
  background-position:center 30%;
}
.hero-scrim {
  position:absolute; inset:0; z-index:1;
  background:rgba(10,22,40,0.52);
}
.hero-panel {
  position:absolute; inset:0; z-index:2;
  background:linear-gradient(90deg,
    rgba(10,22,40,0.78) 0%,
    rgba(10,22,40,0.78) 40%,
    rgba(10,22,40,0.0) 68%
  );
}
.hero-geo {
  position:absolute; right:5%; bottom:0;
  z-index:3; opacity:0.055; pointer-events:none;
}
.hero-content {
  position:relative; z-index:10;
  max-width:var(--max-w);
  margin:0 auto;
  padding:calc(var(--nav-h) + 32px) 80px 0;
  width:100%;
}
.hero-eyebrow {
  display:inline-flex; align-items:center; gap:12px;
  font-size:11px; letter-spacing:0.18em;
  text-transform:uppercase; color:var(--signal-cyan);
  margin-bottom:22px;
  opacity:0; animation:slideUp 550ms 200ms ease-out forwards;
}
.hero-eyebrow::before {
  content:""; display:block;
  width:28px; height:1px; background:var(--signal-cyan); flex-shrink:0;
}
.hero-h1 {
  font-size:clamp(36px,4.6vw,58px);
  color:var(--pure-white);
  line-height:1.1; letter-spacing:-0.01em;
  max-width:660px; margin-bottom:20px;
  opacity:0; animation:slideUp 600ms 340ms ease-out forwards;
}
.hero-h1 em { font-style:normal; color:var(--signal-cyan); }
.hero-sub {
  font-size:clamp(15px,1.5vw,18px);
  color:rgba(255,255,255,0.78);
  line-height:1.7; max-width:500px; margin-bottom:42px;
  opacity:0; animation:slideUp 600ms 460ms ease-out forwards;
}
.hero-btns {
  display:flex; gap:14px; flex-wrap:wrap;
  opacity:0; animation:slideUp 600ms 580ms ease-out forwards;
}
.btn-hero-primary {
  display:inline-flex; align-items:center; gap:9px;
  height:50px; padding:0 28px;
  background:var(--signal-cyan); color:var(--pure-white);
  font-family:var(--font); font-size:14px; letter-spacing:0.05em;
  border-radius:2px; border:none; cursor:pointer;
  transition:background 200ms ease;
}
.btn-hero-primary:hover { background:#0082b8; }
.btn-hero-primary svg {
  width:15px; height:15px; stroke:currentColor;
  fill:none; stroke-width:2;
  transition:transform 200ms ease;
}
.btn-hero-primary:hover svg { transform:translateX(3px); }
.btn-hero-ghost {
  display:inline-flex; align-items:center;
  height:50px; padding:0 28px;
  background:transparent; color:var(--pure-white);
  font-family:var(--font); font-size:14px; letter-spacing:0.05em;
  border-radius:2px; border:1.5px solid rgba(255,255,255,0.36);
  cursor:pointer; transition:border-color 200ms ease, background 200ms ease;
}
.btn-hero-ghost:hover { border-color:rgba(255,255,255,0.68); background:rgba(255,255,255,0.05); }
.hero-scroll {
  position:absolute; bottom:36px; left:80px;
  z-index:10;
  display:flex; flex-direction:column; align-items:center; gap:8px;
  opacity:0; animation:fadeIn 800ms 1000ms ease-out forwards;
}
.scroll-track {
  width:1px; height:42px;
  background:rgba(255,255,255,0.12); overflow:hidden; position:relative;
}
.scroll-track::after {
  content:""; position:absolute;
  top:-100%; left:0; width:1px; height:100%;
  background:var(--signal-cyan);
  animation:scrollDrop 2.2s 1.5s ease-in-out infinite;
}
.scroll-label {
  font-size:9px; letter-spacing:0.2em;
  text-transform:uppercase; color:rgba(255,255,255,0.3);
  writing-mode:vertical-rl;
}

@keyframes slideUp {
  from { opacity:0; transform:translateY(18px); }
  to   { opacity:1; transform:translateY(0); }
}
@keyframes fadeIn {
  from { opacity:0; } to { opacity:1; }
}
@keyframes scrollDrop {
  0%   { top:-100%; }
  40%, 100% { top:100%; }
}


/* ════════════════════════════════
   STATS STRIP
════════════════════════════════ */
.stats-strip {
  background:var(--brand-navy);
  border-top:1px solid rgba(255,255,255,0.06);
  border-bottom:1px solid rgba(255,255,255,0.06);
}
.stats-inner {
  max-width:var(--max-w);
  margin:0 auto;
  padding:0 80px;
  display:flex;
  align-items:stretch;
}
.stat-item {
  flex:1;
  padding:36px 0;
  text-align:center;
  transition:background 220ms ease;
  cursor:default;
}
.stat-item:hover { background:rgba(0,153,214,0.08); }
.stat-n {
  display:block;
  font-size:44px;
  color:var(--signal-cyan);
  line-height:1;
  margin-bottom:10px;
  letter-spacing:-0.02em;
}
.stat-l {
  font-size:11px;
  color:rgba(255,255,255,0.5);
  letter-spacing:0.12em;
  text-transform:uppercase;
}
.stat-divider {
  width:1px;
  background:rgba(255,255,255,0.08);
  flex-shrink:0;
  margin:20px 0;
}


/* ════════════════════════════════
   ABOUT
════════════════════════════════ */
.about {
  padding:96px 0;
  background:var(--pure-white);
  overflow:hidden;
}
.about-inner {
  max-width:var(--max-w);
  margin:0 auto;
  padding:0 80px;
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:80px;
  align-items:center;
}

/* Left */
.eyebrow {
  display:inline-flex;
  align-items:center;
  gap:10px;
  font-size:11px;
  letter-spacing:0.16em;
  text-transform:uppercase;
  color:var(--signal-cyan);
  margin-bottom:16px;
}
.eyebrow::before {
  content:"";
  display:block;
  width:24px; height:1px;
  background:var(--signal-cyan);
  flex-shrink:0;
}
.about-h2 {
  font-size:clamp(26px,2.8vw,38px);
  color:var(--ink-navy);
  line-height:1.15;
  letter-spacing:-0.01em;
  margin-bottom:24px;
}
.about-body {
  font-size:15px;
  color:var(--gray-700);
  line-height:1.8;
  margin-bottom:14px;
}
.about-body.lead {
  font-size:17px;
  color:var(--charcoal);
  margin-bottom:16px;
}

/* Micro stats row */
.about-microstats {
  display:grid;
  grid-template-columns:repeat(4,1fr);
  border:1px solid var(--gray-100);
  border-radius:4px;
  overflow:hidden;
  margin-top:36px;
}
.micro-stat {
  padding:20px 12px;
  text-align:center;
  border-right:1px solid var(--gray-100);
  transition:background 220ms ease;
  cursor:default;
}
.micro-stat:last-child { border-right:none; }
.micro-stat:hover { background:var(--frost); }
.micro-num {
  display:block;
  font-size:28px;
  color:var(--signal-cyan);
  line-height:1;
  letter-spacing:-0.02em;
  margin-bottom:6px;
}
.micro-lbl {
  font-size:10px;
  color:var(--gray-500);
  letter-spacing:0.1em;
  text-transform:uppercase;
  line-height:1.3;
}

/* Right */
.about-right { position:relative; }

.about-img-outer {
  position:relative;
  border-radius:4px;
  overflow:hidden;
  height:460px;
}
.about-img-photo {
  width:100%; height:100%;
  object-fit:cover;
  object-position:center 25%;
  display:block;
}
.about-img-outer::after {
  content:"";
  position:absolute; inset:0;
  border:1px solid rgba(0,153,214,0.2);
  border-radius:4px;
  pointer-events:none;
}
.about-caption {
  position:absolute;
  bottom:24px; left:-28px;
  background:var(--pure-white);
  border:1px solid var(--gray-100);
  border-left:3px solid var(--signal-cyan);
  border-radius:4px;
  padding:14px 18px;
  box-shadow:0 8px 28px rgba(10,22,40,0.10);
  z-index:2;
}
.caption-label {
  font-size:10px;
  letter-spacing:0.1em;
  text-transform:uppercase;
  color:var(--gray-500);
  margin-bottom:4px;
  display:block;
}
.caption-val {
  font-size:14px;
  color:var(--ink-navy);
  display:block;
}
.about-geo {
  position:absolute;
  top:-16px; right:-16px;
  opacity:0.06; pointer-events:none; z-index:0;
}


/* ════════════════════════════════
   SCROLL REVEAL
════════════════════════════════ */
.reveal {
  opacity:0;
  transform:translateY(24px);
  transition:opacity 550ms ease-out, transform 550ms ease-out;
}
.reveal.visible { opacity:1; transform:translateY(0); }
.reveal-d1 { transition-delay:80ms; }
.reveal-d2 { transition-delay:160ms; }
.reveal-d3 { transition-delay:240ms; }
.reveal-d4 { transition-delay:320ms; }

@media (prefers-reduced-motion:reduce) {
  .reveal { opacity:1; transform:none; transition:none; }
  .hero-eyebrow,.hero-h1,.hero-sub,.hero-btns,.hero-scroll {
    animation:none; opacity:1;
  }
  .scroll-track::after { animation:none; }
}


/* ════════════════════════════════
   PLACEHOLDER
════════════════════════════════ */
.placeholder {
  padding:80px;
  background:var(--cloud-white);
  display:flex; align-items:center; justify-content:center;
  border-top:1px solid var(--gray-100);
  min-height:200px;
}
.placeholder p {
  font-size:13px; letter-spacing:0.1em;
  text-transform:uppercase; color:var(--gray-300);
}



/* ════════════════════════════════
   CORE CAPABILITIES (SCROLL)
════════════════════════════════ */
.capabilities {
  background: var(--pure-white);
  padding: 96px 0 80px;
  overflow: hidden;
}
.capabilities-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 80px;
}
.capabilities-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 40px;
  margin-bottom: 48px;
}
.capabilities-header {
  max-width: 680px;
}
.capabilities-h2 {
  font-size: 44px;
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.015em;
  color: var(--ink-navy);
  margin: 12px 0 0;
}
.capabilities-h2 em {
  color: var(--signal-cyan);
  font-style: normal;
}
.capabilities-lead {
  font-size: 18px;
  font-weight: 300;
  line-height: 1.6;
  color: var(--gray-700);
  margin-top: 16px;
  max-width: 600px;
}
.cap-nav {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 16px;
  flex-shrink: 0;
  justify-content: flex-end;
}
.cap-nav-btns {
  display: flex;
  gap: 8px;
}
.cap-all-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.10em;
  color: var(--ink-navy);
  text-decoration: none;
  white-space: nowrap;
  transition: color 200ms ease;
}
.cap-all-link:hover { color: var(--signal-cyan); }
.cap-all-link svg {
  width: 14px; height: 14px;
  stroke: currentColor; stroke-width: 2;
  fill: none; stroke-linecap: round; stroke-linejoin: round;
  transition: transform 200ms ease;
}
.cap-all-link:hover svg { transform: translateX(3px); }
.cap-nav-btn {
  width: 48px;
  height: 48px;
  border: 1px solid var(--gray-100);
  border-radius: 2px;
  background: var(--pure-white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 200ms ease-out, border-color 200ms ease-out;
}
.cap-nav-btn:hover {
  background: var(--ink-navy);
  border-color: var(--ink-navy);
}
.cap-nav-btn:hover svg { stroke: #fff; }
.cap-nav-btn svg {
  width: 18px; height: 18px;
  stroke: var(--ink-navy); stroke-width: 2;
  fill: none; stroke-linecap: round; stroke-linejoin: round;
}

/* Scroll container */
.cap-scroll-wrapper {
  margin: 0 -80px;
  padding: 0 80px;
  overflow: visible;
}
.cap-scroll {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
  scroll-behavior: smooth;
  padding-right: 160px;
  padding-bottom: 4px;
}
.cap-scroll::-webkit-scrollbar { display: none; }

/* Individual card */
.cap-card {
  flex: 0 0 380px;
  height: 440px;
  border-radius: 6px;
  overflow: hidden;
  position: relative;
  scroll-snap-align: start;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

/* Card background — gradient overlay on image placeholder */
.cap-card-bg {
  position: absolute;
  inset: 0;
  background: var(--brand-navy);
  background-size: cover;
  background-position: center;
  z-index: 0;
  transition: transform 450ms ease-out;
}
.cap-card:hover .cap-card-bg { transform: scale(1.05); }

/* Geometric pattern overlay */
.cap-card-geo {
  position: absolute;
  inset: 0;
  z-index: 1;
  opacity: 0;
}

/* Gradient scrim at bottom */
.cap-card-scrim {
  position: absolute;
  inset: 0;
  z-index: 2;
  background: linear-gradient(to top,
    rgba(10,22,40,0.95) 0%,
    rgba(10,22,40,0.7) 35%,
    rgba(10,22,40,0.35) 70%,
    rgba(10,22,40,0.2) 100%);
}

/* Card content */
.cap-card-content {
  position: relative;
  z-index: 3;
  padding: 32px 28px;
  display: flex;
  flex-direction: column;
  flex: 1;
  justify-content: flex-end;
}
.cap-number {
  position: absolute;
  top: 24px;
  left: 28px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--signal-cyan);
  display: flex;
  align-items: center;
  gap: 8px;
}
.cap-number::before {
  content: "";
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--signal-cyan);
}
.cap-card-icon {
  width: 44px; height: 44px;
  background: rgba(0,153,214,0.15);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}
.cap-card-icon svg {
  width: 22px; height: 22px;
  stroke: var(--signal-cyan);
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
}
.cap-card-title {
  font-size: 24px;
  font-weight: 700;
  line-height: 1.2;
  color: #fff;
  margin-bottom: 10px;
}
.cap-card-desc {
  font-size: 14px;
  font-weight: 300;
  line-height: 1.55;
  color: rgba(255,255,255,0.7);
  max-height: 0;
  overflow: hidden;
  opacity: 0;
  transition: max-height 350ms ease-out, opacity 300ms ease-out, margin 300ms ease-out;
  margin-bottom: 0;
}
.cap-card:hover .cap-card-desc {
  max-height: 100px;
  opacity: 1;
  margin-bottom: 16px;
}
.cap-card-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--signal-cyan);
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 250ms ease-out 80ms, transform 250ms ease-out 80ms;
}
.cap-card:hover .cap-card-link {
  opacity: 1;
  transform: translateY(0);
}
.cap-card-link svg {
  width: 14px; height: 14px;
  stroke: var(--signal-cyan); stroke-width: 2; fill: none;
}

/* Progress bar */
.cap-progress {
  max-width: var(--max-w);
  margin: 32px auto 0;
  padding: 0 80px;
  display: flex;
  align-items: center;
  gap: 16px;
}
.cap-progress-track {
  flex: 1;
  height: 2px;
  background: var(--gray-100);
  border-radius: 2px;
  overflow: hidden;
}
.cap-progress-fill {
  height: 100%;
  width: 42%;
  background: var(--signal-cyan);
  border-radius: 2px;
  transition: width 300ms ease-out;
}
.cap-progress-count {
  font-size: 12px;
  font-weight: 500;
  color: var(--gray-500);
  flex-shrink: 0;
  border: none;
  outline: none;
  background: none;
  border-radius: 0;
  box-shadow: none;
  padding: 0;
  font-family: var(--font);
  letter-spacing: 0.04em;
}

/* Card BG color variations */
