  border-bottom: 1px solid var(--gray-100);
  display: flex;
  flex-direction: column;
  min-height: 220px;
  transition: background 250ms ease-out;
  cursor: pointer;
}
.ind-tile:nth-child(4n) { border-right: none; }
.ind-tile:nth-last-child(-n+4) { border-bottom: none; }
.ind-tile:hover { background: var(--frost); }
.ind-tile:hover .ind-icon { background: var(--signal-cyan); }
.ind-tile:hover .ind-icon svg { stroke: #fff; }
.ind-icon {
  width: 44px;
  height: 44px;
  background: var(--frost);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 22px;
  transition: background 250ms ease-out;
}
.ind-icon svg {
  width: 24px; height: 24px;
  stroke: var(--signal-cyan);
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  transition: stroke 250ms ease-out;
}
.ind-title {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.3;
  color: var(--ink-navy);
  margin-bottom: 10px;
}
.ind-desc {
  font-size: 14px;
  font-weight: 300;
  line-height: 1.55;
  color: var(--gray-700);
}


/* ════════════════════════════════
   TECHNOLOGY PARTNERS
════════════════════════════════ */
.partners {
  background: var(--pure-white);
  padding: 96px 0;
}
.partners-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 80px;
}
.partners-header {
  max-width: 820px;
  margin-bottom: 56px;
}
.partners-h2 {
  font-size: 44px;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.01em;
  color: var(--ink-navy);
  margin: 12px 0 20px;
}
.partners-lead {
  font-size: 18px;
  font-weight: 300;
  line-height: 1.6;
  color: var(--gray-700);
  max-width: 680px;
}
.partner-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  background: var(--pure-white);
  border: 1px solid var(--gray-100);
  border-radius: 4px;
  overflow: hidden;
}
.partner-cell {
  height: 110px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-right: 1px solid var(--gray-100);
  border-bottom: 1px solid var(--gray-100);
  transition: background 250ms ease-out;
  padding: 20px;
}
.partner-cell:nth-child(6n) { border-right: none; }
.partner-cell:nth-last-child(-n+6) { border-bottom: none; }
.partner-cell:hover { background: var(--cloud-white); }
.partner-name {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--gray-300);
  transition: color 250ms ease-out;
  text-align: center;
  line-height: 1.1;
}
.partner-cell:hover .partner-name { color: var(--ink-navy); }
.partner-cell.accent:hover .partner-name { color: var(--signal-cyan); }

.partners-footer {
  margin-top: 40px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
}
.partners-count {
  font-size: 14px;
  font-weight: 300;
  color: var(--gray-500);
}
.partners-count strong {
  color: var(--ink-navy);
  font-weight: 700;
}
.partners-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--signal-cyan);
  transition: gap 250ms ease-out;
}
.partners-link:hover { gap: 12px; }
.partners-link svg {
  width: 14px; height: 14px;
  stroke: var(--signal-cyan);
  stroke-width: 1.8;
  fill: none;
}

/* ════════════════════════════════
   CTA BAND
════════════════════════════════ */
.cta-band {
  background: var(--ink-navy);
  padding: 112px 0;
  position: relative;
  overflow: hidden;
}
.cta-band::before {
  content: "";
  position: absolute;
  top: -80px;
  right: -80px;
  width: 420px;
  height: 420px;
  background: radial-gradient(circle, rgba(0,153,214,0.18) 0%, transparent 60%);
  pointer-events: none;
}
.cta-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 80px;
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 80px;
  align-items: center;
}
.cta-eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--signal-cyan);
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}
.cta-eyebrow::before {
  content: "";
  width: 28px;
  height: 1.5px;
  background: var(--signal-cyan);
}
.cta-h2 {
  font-size: 48px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.015em;
  color: #fff;
  margin-bottom: 24px;
}
.cta-h2 em {
  color: var(--signal-cyan);
  font-style: normal;
}
.cta-sub {
  font-size: 18px;
  font-weight: 300;
  line-height: 1.6;
  color: var(--gray-300);
  max-width: 540px;
}
.cta-actions {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: flex-start;
}
.cta-primary {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: var(--signal-cyan);
  color: #fff;
  padding: 18px 32px;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border-radius: 2px;
  transition: background 200ms ease-out;
}
.cta-primary:hover { background: #0080B3; }
.cta-primary svg {
  width: 16px; height: 16px;
  stroke: #fff; stroke-width: 2; fill: none;
}
.cta-meta {
  margin-top: 8px;
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
}
.cta-meta-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  font-weight: 300;
  color: var(--gray-300);
}
.cta-meta-item svg {
  width: 16px; height: 16px;
  stroke: var(--signal-cyan); stroke-width: 1.6; fill: none;
}

/* ════════════════════════════════
   FOOTER
════════════════════════════════ */
.site-footer {
  background: var(--brand-navy);
  color: #fff;
  padding: 80px 0 0;
}
.footer-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 80px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1.2fr;
  gap: 64px;
  padding-bottom: 64px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-brand-block img {
  height: 40px;
  margin-bottom: 20px;
  filter: brightness(0) invert(1);
}
.footer-tagline {
  font-size: 14px;
  font-weight: 300;
  line-height: 1.6;
  color: var(--gray-300);
  margin-bottom: 24px;
  max-width: 300px;
}
.footer-social {
  display: flex;
  gap: 10px;
}
.footer-social a {
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 200ms ease-out, border-color 200ms ease-out;
}
.footer-social a:hover {
  background: var(--signal-cyan);
  border-color: var(--signal-cyan);
}
.footer-social svg {
  width: 16px; height: 16px;
  fill: #fff;
}
.footer-col-title {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--signal-cyan);
  margin-bottom: 20px;
}
.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.footer-links a {
  font-size: 14px;
  font-weight: 300;
  color: rgba(255,255,255,0.78);
  transition: color 200ms ease-out;
}
.footer-links a:hover { color: var(--signal-cyan); }
.footer-contact {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.footer-contact-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 14px;
  font-weight: 300;
  color: rgba(255,255,255,0.78);
  line-height: 1.5;
}
.footer-contact-item svg {
  width: 16px; height: 16px;
  stroke: var(--signal-cyan); stroke-width: 1.6; fill: none;
  flex-shrink: 0;
  margin-top: 2px;
}
.footer-contact-item a { color: inherit; transition: color 200ms ease-out; }
.footer-contact-item a:hover { color: var(--signal-cyan); }
.footer-bottom {
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-copy {
  font-size: 12px;
  font-weight: 300;
  color: var(--gray-500);
}


/* ════════════════════════════════
   RESPONSIVE
════════════════════════════════ */
@media (max-width:1024px) {
  .nav-inner { padding:0 40px; }
  .hero-content { padding:0 40px; padding-top:var(--nav-h); }
  .hero-scroll { left:40px; }
  .stats-inner { padding:0 40px; }
  .about-inner { padding:0 40px; gap:48px; }
  .capabilities-inner { padding: 0 40px; }
  .cap-grid { grid-template-columns: repeat(2, 1fr); }
  .industries-inner { padding: 0 40px; }
  .ind-grid { grid-template-columns: repeat(2, 1fr); }
  .ind-tile { border-right: 1px solid var(--gray-100); border-bottom: 1px solid var(--gray-100); }
  .ind-tile:nth-child(4n) { border-right: 1px solid var(--gray-100); }
  .ind-tile:nth-child(2n) { border-right: none; }
  .ind-tile:nth-last-child(-n+4) { border-bottom: 1px solid var(--gray-100); }
  .ind-tile:nth-last-child(-n+2) { border-bottom: none; }
  .partners-inner { padding: 0 40px; }
  .partner-grid { grid-template-columns: repeat(4, 1fr); }
  .partner-cell { border-right: 1px solid var(--gray-100); border-bottom: 1px solid var(--gray-100); }
  .partner-cell:nth-child(6n) { border-right: 1px solid var(--gray-100); }
  .partner-cell:nth-child(4n) { border-right: none; }
  .partner-cell:nth-last-child(-n+6) { border-bottom: 1px solid var(--gray-100); }
  .cta-inner { padding: 0 40px; grid-template-columns: 1fr; gap: 40px; }
  .cta-h2 { font-size: 40px; }
  .footer-inner { padding: 0 40px; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 48px; }
}
@media (max-width:768px) {
  .nav-links { display:none; }
  .nav-inner { padding:0 24px; }
  .hero-content { padding:0 24px; padding-top:var(--nav-h); }
  .hero-scroll { display:none; }
  .hero-h1 { font-size:30px; }
  .hero-panel { background:rgba(10,22,40,0.65); }
  .stats-inner { padding:0; flex-wrap:wrap; }
  .stat-item { flex:1 1 40%; padding:28px 0; }
  .stat-divider { display:none; }
  .stat-n { font-size:36px; }
  .about { padding:56px 0; }
  .about-inner { padding:0 24px; grid-template-columns:1fr; gap:40px; }
  .about-right { display:none; }
  .about-microstats { grid-template-columns:repeat(2,1fr); }
  .capabilities { padding: 56px 0; }
  .capabilities-inner { padding: 0 24px; }
  .capabilities-h2 { font-size: 30px; }
  .capabilities-lead { font-size: 16px; }
  .cap-grid { grid-template-columns: 1fr; gap: 16px; }
  .industries { padding: 56px 0; }
  .industries-inner { padding: 0 24px; }
  .industries-h2 { font-size: 30px; }
  .industries-lead { font-size: 16px; }
  .ind-grid { grid-template-columns: 1fr; }
  .ind-tile { border-right: none; border-bottom: 1px solid var(--gray-100); }
  .ind-tile:last-child { border-bottom: none; }
  .partners { padding: 56px 0; }
  .partners-inner { padding: 0 24px; }
  .partners-h2 { font-size: 30px; }
  .partners-lead { font-size: 16px; }
  .partner-grid { grid-template-columns: repeat(2, 1fr); }
  .partner-cell { height: 90px; }
  .partner-cell { border-right: 1px solid var(--gray-100); border-bottom: 1px solid var(--gray-100); }
  .partner-cell:nth-child(2n) { border-right: none; }
  .cta-band { padding: 72px 0; }
  .cta-inner { padding: 0 24px; }
  .cta-h2 { font-size: 30px; }
  .cta-sub { font-size: 16px; }
  .footer-inner { padding: 0 24px; }
  .footer-grid { grid-template-columns: 1fr; gap: 40px; padding-bottom: 40px; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .micro-stat:nth-child(1),
  .micro-stat:nth-child(2) { border-bottom:1px solid var(--gray-100); }
  .micro-stat:nth-child(2) { border-right:none; }
}



/* ════════════════════════════════
   LEADERS / CLIENTS SECTION
════════════════════════════════ */
.leaders {
  padding: 96px 0;
  background: var(--cloud-white);
  overflow: hidden;
}

.leaders-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 80px;
}

.leaders-header {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: end;
  margin-bottom: 64px;
}

.leaders-header-left {}

.leaders-h2 {
  font-size: clamp(26px, 2.8vw, 38px);
  color: var(--ink-navy);
  line-height: 1.15;
  letter-spacing: -0.01em;
  margin-bottom: 0;
}

.leaders-header-right p {
  font-size: 16px;
  color: var(--gray-700);
  line-height: 1.75;
  max-width: 480px;
}

/* Divider rule below header */
.leaders-rule {
  height: 1px;
  background: var(--gray-100);
  margin-bottom: 56px;
}

/* Logo grid */
.logo-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0;
  border: 1px solid var(--gray-100);
  border-radius: 4px;
  overflow: hidden;
}

.logo-cell {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px 28px;
  border-right: 1px solid var(--gray-100);
  border-bottom: 1px solid var(--gray-100);
  background: var(--pure-white);
  transition: background 250ms ease, border-color 250ms ease;
  min-height: 96px;
  position: relative;
  overflow: hidden;
}

/* Remove right border on last in each row */
.logo-cell:nth-child(5n) { border-right: none; }
/* Remove bottom border on last row — handled by JS, use last-child fallback */
.logo-cell:nth-last-child(-n+5) { border-bottom: none; }

.logo-cell:hover {
  background: var(--frost);
  border-color: rgba(0,153,214,0.15);
  z-index: 1;
}

/* Cyan left accent on hover */
.logo-cell::before {
  content: "";
  position: absolute;
  left: 0; top: 20%; bottom: 20%;
  width: 2px;
  background: var(--signal-cyan);
  transform: scaleY(0);
  transition: transform 250ms ease;
  border-radius: 1px;
}
.logo-cell:hover::before { transform: scaleY(1); }

/* Logo image — greyscale default, colour on hover */
.logo-cell img {
  max-width: 120px;
  max-height: 44px;
  width: auto;
  height: auto;
  object-fit: contain;
  filter: grayscale(100%) opacity(55%);
  transition: filter 300ms ease;
  display: block;
  margin: 0 auto;
}
.logo-cell:hover img {
  filter: grayscale(0%) opacity(100%);
}

/* SVG placeholder logos — used until real logos are supplied */
.logo-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}
.logo-placeholder .org-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--gray-300);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-align: center;
  line-height: 1.2;
  transition: color 250ms ease;
}
.logo-placeholder .org-icon {
  width: 28px; height: 28px;
  opacity: 0.25;
  transition: opacity 250ms ease;
}
.logo-cell:hover .org-name { color: var(--gray-500); }
.logo-cell:hover .org-icon { opacity: 0.5; }

/* "And many more" footer note */
.logo-footer {
  margin-top: 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.logo-count-note {
  font-size: 13px;
  color: var(--gray-500);
  display: flex;
  align-items: center;
  gap: 8px;
}
.logo-count-note::before {
  content: "";
  display: block;
  width: 20px; height: 1px;
  background: var(--gray-300);
}
.logo-count-note strong {
  color: var(--signal-cyan);
}
.clients-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 13px;
  color: var(--signal-cyan);
  letter-spacing: 0.04em;
  border-bottom: 1px solid rgba(0,153,214,0.3);
  padding-bottom: 1px;
  transition: gap 200ms ease, border-color 200ms;
}
.clients-link:hover { gap: 11px; border-color: var(--signal-cyan); }
.clients-link svg {
  width: 14px; height: 14px;
  stroke: currentColor; fill: none; stroke-width: 2;
  transition: transform 200ms;
}
.clients-link:hover svg { transform: translateX(3px); }

/* Responsive */
@media (max-width: 1024px) {
  .leaders-inner { padding: 0 40px; }
  .logo-grid { grid-template-columns: repeat(4, 1fr); }
  .logo-cell:nth-child(5n) { border-right: 1px solid var(--gray-100); }
  .logo-cell:nth-child(4n) { border-right: none; }
  .logo-cell:nth-last-child(-n+4) { border-bottom: none; }
}
@media (max-width: 768px) {
  .leaders { padding: 56px 0; }
  .leaders-inner { padding: 0 24px; }
  .leaders-header { grid-template-columns: 1fr; gap: 20px; margin-bottom: 40px; }
  .logo-grid { grid-template-columns: repeat(3, 1fr); }
  .logo-cell:nth-child(4n) { border-right: 1px solid var(--gray-100); }
  .logo-cell:nth-child(3n) { border-right: none; }
}

